let _db: ReturnType<typeof drizzle> | null = null;
export async function getDb() { if (!_db && process.env.DATABASE_URL) { try { _db = drizzle(process.env.DATABASE_URL); } catch (error) { console.warn("[Database] Failed to connect:", error); _db = null; } } return _db; }

export async function upsertUser(user: InsertUser): Promise<void> { if (!user.openId) throw new Error("User openId is required for upsert"); const db = await getDb(); if (!db) return; const values: InsertUser = { openId: user.openId }; const updateSet: Record<string, unknown> = {}; for (const field of ["name", "email", "loginMethod"] as const) { if (user[field] !== undefined) { values[field] = user[field] ?? null; updateSet[field] = user[field] ?? null; } } values.lastSignedIn = user.lastSignedIn ?? new Date(); updateSet.lastSignedIn = values.lastSignedIn; if (user.role) { values.role = user.role; updateSet.role = user.role; } else if (user.openId === ENV.ownerOpenId) { values.role = "admin"; updateSet.role = "admin"; } await db.insert(users).values(values).onDuplicateKeyUpdate({ set: updateSet }); }
export async function getUserByOpenId(openId: string) { const db = await getDb(); if (!db) return undefined; const result = await db.select().from(users).where(eq(users.openId, openId)).limit(1); return result[0]; }
export async function getUserById(id: number) { const db = await getDb(); if (!db) return undefined; const result = await db.select().from(users).where(eq(users.id, id)).limit(1); return result[0]; }

export async function getTeacherProfile(userId: number) { const db = await getDb(); if (!db) return undefined; const result = await db.select().from(teacherProfiles).where(eq(teacherProfiles.userId, userId)).limit(1); return result[0]; }
export async function updateTeacherAvatar(userId: number, avatarUrl: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(teacherProfiles).set({ avatarUrl }).where(eq(teacherProfiles.userId, userId)); await recordChange(userId, { category: "settings", action: "updated", entityName: "الصورة الشخصية", details: "تم تحديث صورة ملف المعلم" }); return getTeacherProfile(userId); }
export async function recordChange(userId: number, input: Omit<typeof changeLogs.$inferInsert, "id" | "userId" | "createdAt">) { const db = await getDb(); if (!db) return; try { await db.insert(changeLogs).values({ ...input, userId }); } catch (error) { console.warn("[ChangeLog] Failed to record change", error); } }
export async function listChangeLogs(userId: number, limit = 80) { const db = await getDb(); if (!db) return []; return db.select().from(changeLogs).where(eq(changeLogs.userId, userId)).orderBy(desc(changeLogs.createdAt)).limit(limit); }
export async function saveTeacherProfile(userId: number, input: Omit<InsertTeacherProfile, "userId">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.insert(teacherProfiles).values({ ...input, userId }).onDuplicateKeyUpdate({ set: input }); await recordChange(userId, { category: "settings", action: "updated", entityName: "إعدادات الحساب", details: "تم حفظ إعدادات المعلم" }); return getTeacherProfile(userId); }
export async function getSchoolWorkspace(userId: number) { const profile = await getTeacherProfile(userId); return { schoolScheduleJson: profile?.schoolScheduleJson ?? null, weeklyEvaluationJson: profile?.weeklyEvaluationJson ?? null }; }
export async function listLearningMaterials(userId: number, groupId?: number) { const db = await getDb(); if (!db) return []; const where = groupId ? and(eq(learningMaterials.userId, userId), eq(learningMaterials.groupId, groupId)) : eq(learningMaterials.userId, userId); return db.select().from(learningMaterials).where(where).orderBy(desc(learningMaterials.createdAt)); }
export async function createLearningMaterial(userId: number, input: Omit<typeof learningMaterials.$inferInsert, "id" | "userId" | "createdAt">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const owned = await db.select({ id: studyGroups.id }).from(studyGroups).where(and(eq(studyGroups.id, input.groupId), eq(studyGroups.userId, userId))).limit(1); if (!owned[0]) throw new Error("GROUP_NOT_FOUND"); const result = await db.insert(learningMaterials).values({ ...input, userId }); return Number(result[0].insertId); }
export async function listStudentLearningMaterials(studentId: number) { const db = await getDb(); if (!db) return []; const record = await db.select({ userId: students.userId, groupId: students.groupId }).from(students).where(eq(students.id, studentId)).limit(1); const student = record[0]; if (!student?.groupId) return []; return db.select().from(learningMaterials).where(and(eq(learningMaterials.userId, student.userId), eq(learningMaterials.groupId, student.groupId))).orderBy(desc(learningMaterials.createdAt)); }
export async function saveSchoolWorkspace(userId: number, input: { schoolScheduleJson: string; weeklyEvaluationJson: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(teacherProfiles).set(input).where(eq(teacherProfiles.userId, userId)); await recordChange(userId, { category: "settings", action: "updated", entityName: "وضع المدرسة", details: "تم تحديث جدول اليوم والتقييم الأسبوعي" }); return getSchoolWorkspace(userId); }

export async function listYearWorkTerms(userId: number) { const db = await getDb(); if (!db) return []; return db.select().from(yearWorkTerms).where(eq(yearWorkTerms.userId, userId)).orderBy(desc(yearWorkTerms.updatedAt)); }
export async function getYearWorkWorkspace(userId: number, termId?: number) { const db = await getDb(); if (!db) return { terms: [], scores: [], attendance: [] }; const terms = await listYearWorkTerms(userId); const selectedTermId = termId && terms.some(term => term.id === termId) ? termId : terms[0]?.id; if (!selectedTermId) return { terms, scores: [], attendance: [] }; const selected = terms.find(term => term.id === selectedTermId); const [scores, attendanceRows] = await Promise.all([db.select().from(yearWorkScores).where(and(eq(yearWorkScores.userId, userId), eq(yearWorkScores.termId, selectedTermId))), selected ? db.select().from(attendance).where(and(eq(attendance.userId, userId), gte(attendance.lessonDate, selected.startsAt), lte(attendance.lessonDate, selected.endsAt))) : Promise.resolve([])]); return { terms, scores, attendance: attendanceRows };
}
export async function saveYearWorkTerm(userId: number, input: { id?: number; term: "first" | "second"; grade: string; startsAt: Date; endsAt: Date; monthsJson: string; studentIdsJson: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const values = { term: input.term, grade: input.grade, startsAt: input.startsAt, endsAt: input.endsAt, monthsJson: input.monthsJson, studentIdsJson: input.studentIdsJson }; if (input.id) { const owned = await db.select({ id: yearWorkTerms.id }).from(yearWorkTerms).where(and(eq(yearWorkTerms.id, input.id), eq(yearWorkTerms.userId, userId))).limit(1); if (!owned[0]) throw new Error("YEAR_WORK_TERM_NOT_FOUND"); await db.update(yearWorkTerms).set(values).where(and(eq(yearWorkTerms.id, input.id), eq(yearWorkTerms.userId, userId))); await recordChange(userId, { category: "assessment", action: "updated", entityName: `أعمال السنة: ${input.grade}`, details: "تم تحديث إعدادات الفصل الدراسي" }); return input.id; }
  const result = await db.insert(yearWorkTerms).values({ ...values, userId }); const id = Number(result[0].insertId); await recordChange(userId, { category: "assessment", action: "created", entityName: `أعمال السنة: ${input.grade}`, details: "تم إنشاء سجل أعمال سنة" }); return id;
}
export async function saveYearWorkScore(userId: number, input: { termId: number; studentId: number; monthKey: string; homeWork: number; activity: number; weeklyEvaluation: number; performanceTasks: number; behavior: number; attendance: number; monthlyExam: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const [term, student] = await Promise.all([db.select({ id: yearWorkTerms.id }).from(yearWorkTerms).where(and(eq(yearWorkTerms.id, input.termId), eq(yearWorkTerms.userId, userId))).limit(1), db.select({ id: students.id, name: students.name }).from(students).where(and(eq(students.id, input.studentId), eq(students.userId, userId))).limit(1)]); if (!term[0] || !student[0]) throw new Error("YEAR_WORK_NOT_FOUND"); const values = { ...input, userId }; await db.insert(yearWorkScores).values(values).onDuplicateKeyUpdate({ set: { homeWork: input.homeWork, activity: input.activity, weeklyEvaluation: input.weeklyEvaluation, performanceTasks: input.performanceTasks, behavior: input.behavior, attendance: input.attendance, monthlyExam: input.monthlyExam } }); await recordChange(userId, { category: "assessment", action: "recorded", entityName: student[0].name, details: `تم رصد أعمال السنة لشهر ${input.monthKey}` }); return true;
}

export async function listGroups(userId: number) { const db = await getDb(); if (!db) return []; return db.select().from(studyGroups).where(eq(studyGroups.userId, userId)).orderBy(desc(studyGroups.createdAt)); }
export async function createGroup(userId: number, input: Omit<InsertStudyGroup, "userId" | "id">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const result = await db.insert(studyGroups).values({ ...input, userId }); await recordChange(userId, { category: "group", action: "created", entityName: input.name, details: `تم إنشاء مجموعة ${input.place}` }); return { id: Number(result[0].insertId), ...input, userId }; }
export async function updateGroup(userId: number, id: number, input: Partial<Omit<InsertStudyGroup, "userId" | "id">>) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ name: studyGroups.name }).from(studyGroups).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId))).limit(1); await db.update(studyGroups).set(input).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId))); await recordChange(userId, { category: "group", action: "updated", entityName: input.name || before[0]?.name || "مجموعة", details: "تم تعديل بيانات المجموعة" }); return true; }
export async function deleteGroup(userId: number, id: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ name: studyGroups.name }).from(studyGroups).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId))).limit(1); await db.delete(studyGroups).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId))); await recordChange(userId, { category: "group", action: "deleted", entityName: before[0]?.name || "مجموعة", details: "تم حذف المجموعة" }); return true; }

export async function listStudents(userId: number) { const db = await getDb(); if (!db) return []; return db.select().from(students).where(eq(students.userId, userId)).orderBy(desc(students.createdAt)); }
async function adjustGroupStudentCount(userId: number, groupId: number | null | undefined, delta: number) { const db = await getDb(); if (!db || !groupId || !delta) return; await db.update(studyGroups).set({ studentsCount: sql`GREATEST(0, ${studyGroups.studentsCount} + ${delta})` }).where(and(eq(studyGroups.id, groupId), eq(studyGroups.userId, userId))); }

export async function createStudent(userId: number, input: Omit<InsertStudent, "userId" | "id">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const groupRows = input.groupId ? await db.select({ fee: studyGroups.fee }).from(studyGroups).where(and(eq(studyGroups.id, input.groupId), eq(studyGroups.userId, userId))).limit(1) : []; const paidAmount = Number(input.paidAmount || 0); const fee = Number(groupRows[0]?.fee || 0); const paid = fee > 0 ? paidAmount >= fee : Boolean(input.paid); const result = await db.insert(students).values({ ...input, paidAmount: String(Math.max(0, paidAmount)), paid, userId }); const studentId = Number(result[0].insertId); if (paidAmount > 0) await db.insert(financialTransactions).values({ userId, studentId, groupId: input.groupId ?? null, kind: "subscription", amount: String(paidAmount), paidAt: new Date(), dueDate: null, description: "دفعة تسجيل الطالب" }); await adjustGroupStudentCount(userId, input.groupId, 1); await recordChange(userId, { category: "student", action: "created", entityName: input.name, details: "تم تسجيل طالب جديد" }); return { id: studentId, ...input, paidAmount: String(Math.max(0, paidAmount)), paid, userId }; }
export async function updateStudent(userId: number, id: number, input: Partial<Omit<InsertStudent, "userId" | "id">>) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ groupId: students.groupId, name: students.name }).from(students).where(and(eq(students.id, id), eq(students.userId, userId))).limit(1); const targetGroupId = input.groupId === undefined ? before[0]?.groupId : input.groupId; const groupRows = targetGroupId ? await db.select({ fee: studyGroups.fee }).from(studyGroups).where(and(eq(studyGroups.id, targetGroupId), eq(studyGroups.userId, userId))).limit(1) : []; const nextAmount = input.paidAmount === undefined ? undefined : Math.max(0, Number(input.paidAmount)); const nextValues = nextAmount === undefined ? input : { ...input, paidAmount: String(nextAmount), paid: Number(groupRows[0]?.fee || 0) > 0 ? nextAmount >= Number(groupRows[0]?.fee || 0) : Boolean(input.paid) }; await db.update(students).set(nextValues).where(and(eq(students.id, id), eq(students.userId, userId))); const previousGroupId = before[0]?.groupId; if (input.groupId !== undefined && input.groupId !== previousGroupId) { await adjustGroupStudentCount(userId, previousGroupId, -1); await adjustGroupStudentCount(userId, input.groupId, 1); } await recordChange(userId, { category: "student", action: "updated", entityName: input.name || before[0]?.name || "طالب", details: "تم تعديل بيانات الطالب" }); return true; }
export async function deleteStudent(userId: number, id: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ groupId: students.groupId, name: students.name }).from(students).where(and(eq(students.id, id), eq(students.userId, userId))).limit(1); await db.delete(students).where(and(eq(students.id, id), eq(students.userId, userId))); await adjustGroupStudentCount(userId, before[0]?.groupId, -1); await recordChange(userId, { category: "student", action: "deleted", entityName: before[0]?.name || "طالب", details: "تم حذف الطالب" }); return true; }

export function normalizeStudentPhone(value: string) { const arabicDigits = "٠١٢٣٤٥٦٧٨٩"; return value.trim().replace(/[٠-٩]/g, digit => String(arabicDigits.indexOf(digit))).replace(/[^0-9+]/g, ""); }
export const normalizeTeacherPhone = normalizeStudentPhone;
export async function getTeacherAccountByPhone(phone: string) { const db = await getDb(); if (!db) return undefined; const rows = await db.select().from(teacherAccounts).where(eq(teacherAccounts.phone, normalizeTeacherPhone(phone))).limit(1); return rows[0]; }
export async function getTeacherAccountByUserId(userId: number) { const db = await getDb(); if (!db) return undefined; const rows = await db.select().from(teacherAccounts).where(eq(teacherAccounts.userId, userId)).limit(1); return rows[0]; }
export async function createPhoneTeacher(input: { name: string; phone: string; subject: string; passwordHash: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const phone = normalizeTeacherPhone(input.phone); const existing = await getTeacherAccountByPhone(phone); if (existing) throw new Error("TEACHER_PHONE_EXISTS"); const userResult = await db.insert(users).values({ openId: `phone:${phone}`, name: input.name, loginMethod: "phone", lastSignedIn: new Date() }); const userId = Number(userResult[0].insertId); await db.insert(teacherProfiles).values({ userId, name: input.name, phone, subject: input.subject }); const accountResult = await db.insert(teacherAccounts).values({ userId, phone, passwordHash: input.passwordHash }); return { id: Number(accountResult[0].insertId), userId, phone }; }
export async function upsertTeacherAccount(userId: number, phone: string, passwordHash: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const normalizedPhone = normalizeTeacherPhone(phone); const existing = await db.select().from(teacherAccounts).where(eq(teacherAccounts.userId, userId)).limit(1); if (existing[0]) { await db.update(teacherAccounts).set({ phone: normalizedPhone, passwordHash, lastSignedIn: new Date() }).where(eq(teacherAccounts.id, existing[0].id)); return { id: existing[0].id, userId, phone: normalizedPhone }; } const result = await db.insert(teacherAccounts).values({ userId, phone: normalizedPhone, passwordHash }); return { id: Number(result[0].insertId), userId, phone: normalizedPhone }; }
export async function touchTeacherAccount(accountId: number) { const db = await getDb(); if (!db) return; await db.update(teacherAccounts).set({ lastSignedIn: new Date() }).where(eq(teacherAccounts.id, accountId)); }
export async function findStudentByPhone(phone: string) { const db = await getDb(); if (!db) return undefined; const target = normalizeStudentPhone(phone); const rows = await db.select().from(students); return rows.find(row => row.phone && normalizeStudentPhone(row.phone) === target); }
