export type AccountSessionType = "teacher" | "student";
export async function createAccountSession(input: { accountType: AccountSessionType; accountId: number; deviceName: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const id = randomUUID(); await db.insert(accountSessions).values({ id, accountType: input.accountType, accountId: input.accountId, deviceName: input.deviceName.slice(0, 220) || "جهاز غير معروف" }); return id; }
export async function isAccountSessionActive(input: { id: string; accountType: AccountSessionType; accountId: number }) { const db = await getDb(); if (!db) return false; const rows = await db.select({ id: accountSessions.id }).from(accountSessions).where(and(eq(accountSessions.id, input.id), eq(accountSessions.accountType, input.accountType), eq(accountSessions.accountId, input.accountId), isNull(accountSessions.revokedAt))).limit(1); return Boolean(rows[0]); }
export async function listAccountSessions(input: { accountType: AccountSessionType; accountId: number }) { const db = await getDb(); if (!db) return []; return db.select({ id: accountSessions.id, deviceName: accountSessions.deviceName, createdAt: accountSessions.createdAt, lastSeenAt: accountSessions.lastSeenAt }).from(accountSessions).where(and(eq(accountSessions.accountType, input.accountType), eq(accountSessions.accountId, input.accountId), isNull(accountSessions.revokedAt))).orderBy(desc(accountSessions.lastSeenAt)); }
export async function revokeAccountSession(input: { id: string; accountType: AccountSessionType; accountId: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(accountSessions).set({ revokedAt: new Date() }).where(and(eq(accountSessions.id, input.id), eq(accountSessions.accountType, input.accountType), eq(accountSessions.accountId, input.accountId), isNull(accountSessions.revokedAt))); return true; }
export async function revokeOtherAccountSessions(input: { currentSessionId: string; accountType: AccountSessionType; accountId: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(accountSessions).set({ revokedAt: new Date() }).where(and(eq(accountSessions.accountType, input.accountType), eq(accountSessions.accountId, input.accountId), ne(accountSessions.id, input.currentSessionId), isNull(accountSessions.revokedAt))); return true; }
export async function getStudentPortalData(studentId: number) { const db = await getDb(); if (!db) return null; const studentRows = await db.select().from(students).where(eq(students.id, studentId)).limit(1); const student = studentRows[0]; if (!student) return null; const [groupRows, attendanceRows, transactionRows, assessmentRows, behaviorRows] = await Promise.all([student.groupId ? db.select().from(studyGroups).where(and(eq(studyGroups.id, student.groupId), eq(studyGroups.userId, student.userId))).limit(1) : Promise.resolve([]), db.select().from(attendance).where(and(eq(attendance.studentId, student.id), eq(attendance.userId, student.userId))).orderBy(desc(attendance.lessonDate)), db.select().from(financialTransactions).where(and(eq(financialTransactions.studentId, student.id), eq(financialTransactions.userId, student.userId))).orderBy(desc(financialTransactions.createdAt)), db.select().from(assessments).where(and(eq(assessments.studentId, student.id), eq(assessments.userId, student.userId))).orderBy(desc(assessments.createdAt)), db.select().from(behaviorRecords).where(and(eq(behaviorRecords.studentId, student.id), eq(behaviorRecords.userId, student.userId))).orderBy(desc(behaviorRecords.createdAt))]); return { student, group: groupRows[0] ?? null, attendance: attendanceRows, transactions: transactionRows, assessments: assessmentRows, behavior: behaviorRows }; }
export async function getStudentAssistantContext(studentId: number) { const portal = await getStudentPortalData(studentId); if (!portal) return null; const teacher = await getTeacherProfile(portal.student.userId); const groupFee = Number(portal.group?.fee || 0); const paidAmount = Number(portal.student.paidAmount || 0); return { student: { name: portal.student.name, grade: portal.student.grade }, teacher: { name: teacher?.name || "المعلم", subject: teacher?.subject || "المادة" }, group: portal.group ? { name: portal.group.name, place: portal.group.place, mode: portal.group.mode, day: portal.group.day, time: portal.group.time, schedule: portal.group.scheduleJson || null } : null, academic: { absencesCount: portal.attendance.filter(row => row.status === "absent").length, attendanceRecords: portal.attendance.length, latestAssessments: portal.assessments.slice(0, 8).map(row => ({ title: row.title, score: row.score, maxScore: row.maxScore, period: row.period })), remainingAmount: Math.max(0, groupFee - paidAmount), currency: "جنيه" } }; }
export async function updateStudentSelfProfile(studentId: number, input: Pick<typeof students.$inferInsert, "age" | "grade" | "avatarUrl">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(students).set(input).where(eq(students.id, studentId)); return getStudentPortalData(studentId); }

