export async function awardStudentPoints(userId: number, input: { studentId: number; source: "attendance" | "homework" | "high_score" | "manual"; points: number; note?: string | null; referenceKey?: string | null }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); if (!Number.isInteger(input.points) || input.points <= 0 || input.points > 1_000) throw new Error("INVALID_POINTS"); const student = (await db.select({ id: students.id, name: students.name }).from(students).where(and(eq(students.id, input.studentId), eq(students.userId, userId))).limit(1))[0]; if (!student) throw new Error("STUDENT_NOT_FOUND"); if (input.referenceKey) { const duplicate = (await db.select({ id: studentPointLedger.id }).from(studentPointLedger).where(eq(studentPointLedger.referenceKey, input.referenceKey)).limit(1))[0]; if (duplicate) return { created: false, balance: await getStudentPointBalance(userId, input.studentId) }; }
  await db.insert(studentPointLedger).values({ userId, studentId: input.studentId, source: input.source, points: input.points, note: input.note ?? null, referenceKey: input.referenceKey ?? null }); await recordChange(userId, { category: "student", action: "recorded", entityName: student.name, details: `تمت إضافة ${input.points} نقطة مكافأة` }); return { created: true, balance: await getStudentPointBalance(userId, input.studentId) }; }
